import React, { useState, useEffect, useRef } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useTheme } from '../context/ThemeContext';
import { searchProducts } from '../services/api';
import { getAdminUser } from '../util/auth';
import AdminNotifications from './AdminNotifications';

// Direct function definition to avoid import issues
const isAdminAuthenticated = () => {
  const adminToken = localStorage.getItem('adminToken');
  return !!adminToken;
};

const Navbar = ({ cartCount, user, onLogout }) => {
  const navigate = useNavigate();
  const { isDarkMode, toggleTheme } = useTheme();
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [showSearch, setShowSearch] = useState(false);
  const [isSearchOpen, setIsSearchOpen] = useState(false);
  const searchInputRef = useRef(null);

  // Trending searches with icons
  const trendingSearches = [
    { term: 'Milk', icon: '🥛', category: 'milk' },
    { term: 'Ghee', icon: '🧈', category: 'ghee' },
    { term: 'Paneer', icon: '🧀', category: 'paneer' },
    { term: 'Curd', icon: '🥣', category: 'curd' },
    { term: 'Cheese', icon: '🧀', category: 'cheese' }
  ];

  // Popular suggestions with icons
  const popularSuggestions = [
    { term: 'Fresh Milk', icon: '🥛', desc: 'Farm fresh daily' },
    { term: 'Desi Ghee', icon: '🧈', desc: 'Pure & natural' },
    { term: 'Cottage Cheese', icon: '🧀', desc: 'Protein rich' }
  ];

  // Handle notification click - redirect to admin payments
  const handleNotificationClick = (orderId) => {
    if (orderId === 'all') {
      // Navigate to admin and go to payments tab
      navigate('/admin');
      setTimeout(() => {
        // This will be handled by Admin component
        window.location.hash = '#payments';
      }, 100);
    } else {
      // Navigate to admin and go to specific payment
      navigate('/admin');
      setTimeout(() => {
        // Store target order ID in sessionStorage for Admin component
        sessionStorage.setItem('targetPayment', orderId);
        window.location.hash = '#payments';
      }, 100);
    }
  };

  
  const handleLogout = () => {
    onLogout();
    if (isAdminAuthenticated()) {
      localStorage.removeItem('adminToken');
      localStorage.removeItem('adminUser');
      window.location.href = '/admin';
    } else {
      navigate('/');
    }
  };

  const handleSearch = async (e) => {
    const query = e.target.value;
    setSearchQuery(query);
    if (query.length >= 1) {
      try {
        const res = await searchProducts(query, 8);
        setSearchResults(res.data);
        setShowSearch(true);
      } catch (error) {
        console.error('Search error:', error);
      }
    } else {
      setSearchResults([]);
      setShowSearch(false);
    }
  };

  const handleSearchClick = () => {
    setIsSearchOpen(true);
    setTimeout(() => {
      searchInputRef.current?.focus();
    }, 100);
  };

  const handleCloseSearch = () => {
    setIsSearchOpen(false);
    setShowSearch(false);
    setSearchQuery('');
    setSearchResults([]);
  };

  const handleTrendingClick = (term, category) => {
    navigate(`/products?category=${category}`);
    handleCloseSearch();
  };

  const handleSuggestionClick = (term) => {
    setSearchQuery(term);
    navigate(`/products?search=${encodeURIComponent(term)}`);
    handleCloseSearch();
  };

  const handleSearchSubmit = (e) => {
    e.preventDefault();
    if (searchQuery.trim()) {
      navigate(`/products?search=${encodeURIComponent(searchQuery)}`);
      setShowSearch(false);
      setSearchQuery('');
    }
  };

  return (
    <nav className="sticky top-4 z-50 transition-all duration-500 px-4">
      {/* Full Glass Effect Container - Ultra Modern Floating Style */}
      <div className={`relative mx-auto max-w-7xl ${isDarkMode ? 'bg-gray-900/60' : 'bg-white/75'} backdrop-blur-[25px] rounded-[2rem] border ${isDarkMode ? 'border-white/20' : 'border-white/60'} shadow-[0_8px_32px_rgba(0,0,0,0.12)] overflow-hidden transition-all duration-500 hover:shadow-[0_12px_40px_rgba(0,0,0,0.18)]`}>
        {/* Animated Mesh Gradient Background */}
        <div className={`absolute inset-0 opacity-30 ${isDarkMode ? 'bg-gradient-to-br from-primary-600/20 via-secondary-600/10 to-primary-600/20' : 'bg-gradient-to-br from-primary-100/40 via-secondary-100/30 to-primary-100/40'} animate-gradient-shift pointer-events-none`}></div>
        
        {/* Glass Reflection Effect */}
        <div className={`absolute inset-0 bg-gradient-to-b ${isDarkMode ? 'from-white/10 via-white/5 to-transparent' : 'from-white/80 via-white/40 to-transparent'} pointer-events-none`}></div>
        
        {/* Animated Shimmer Effect */}
        <div className={`absolute inset-0 bg-gradient-to-r ${isDarkMode ? 'from-transparent via-primary-500/10 via-secondary-500/10 to-transparent' : 'from-transparent via-primary-400/15 via-secondary-400/15 to-transparent'} animate-gradient-x pointer-events-none`}></div>
        
        {/* Floating Particles Effect */}
        <div className="absolute inset-0 overflow-hidden pointer-events-none">
          {[...Array(5)].map((_, i) => (
            <div
              key={i}
              className={`absolute w-2 h-2 rounded-full ${isDarkMode ? 'bg-primary-500/30' : 'bg-primary-400/40'} animate-float`}
              style={{
                left: `${20 + i * 15}%`,
                top: `${30 + (i % 2) * 40}%`,
                animationDelay: `${i * 0.5}s`
              }}
            />
          ))}
        </div>
        
        {/* Top Highlight Line */}
        <div className={`absolute inset-x-0 top-0 h-[2px] ${isDarkMode ? 'bg-gradient-to-r from-transparent via-primary-500/50 via-secondary-500/50 to-transparent' : 'bg-gradient-to-r from-transparent via-primary-400/60 via-secondary-400/60 to-transparent'}`}></div>
        
        {/* Bottom Soft Glow */}
        <div className={`absolute inset-x-0 bottom-0 h-8 ${isDarkMode ? 'bg-gradient-to-t from-primary-500/10 to-transparent' : 'bg-gradient-to-t from-primary-400/20 to-transparent'} blur-xl`}></div>
        
        <div className="relative z-10 container mx-auto px-4">
          <div className="flex items-center justify-between h-16">
          <Link to="/" className="flex items-center space-x-3 group">
            <div className="relative">
              {/* Milk Bottle with Modern Glass Effect */}
              <div className="w-10 h-10 relative">
                <div className="absolute inset-0 bg-gradient-to-br from-primary-400 to-secondary-500 rounded-xl flex items-center justify-center transform transition-all duration-300 group-hover:rotate-12 group-hover:scale-110 shadow-lg group-hover:shadow-primary-500/50">
                  {/* Milk Bottle Icon */}
                  <svg className="w-6 h-6 text-white drop-shadow-md" fill="currentColor" viewBox="0 0 24 24">
                    <path d="M7 2v2h1v14a4 4 0 004 4h0a4 4 0 004-4V4h1V2H7zm2 2h6v14a2 2 0 01-2 2h0a2 2 0 01-2-2V4z"/>
                    <path d="M9 6h6v2H9z" opacity="0.3"/>
                  </svg>
                </div>
                {/* Animated Glow Ring */}
                <div className="absolute -inset-1 bg-gradient-to-r from-primary-500 to-secondary-500 rounded-xl blur opacity-0 group-hover:opacity-50 transition-opacity duration-300"></div>
                {/* Milk Drop Animation */}
                <div className="absolute -top-1 -right-1 w-3 h-3 bg-primary-300 rounded-full animate-bounce opacity-0 group-hover:opacity-100">
                  <div className="w-full h-full bg-primary-400 rounded-full animate-ping"></div>
                </div>
              </div>
            </div>
            <div className="flex flex-col">
              <span className={`text-xl font-bold bg-gradient-to-r bg-clip-text text-transparent ${isDarkMode ? 'from-white to-gray-300' : 'from-primary-600 to-secondary-600'}`}>
                MilkMitra
              </span>
              <span className={`text-xs ${isDarkMode ? 'text-gray-400' : 'text-gray-500'}`}>Fresh Daily</span>
            </div>
          </Link>

          <form onSubmit={handleSearchSubmit} className="hidden md:block relative">
            <div className="relative">
              <input
                type="text"
                value={searchQuery}
                onChange={handleSearch}
                onFocus={() => searchQuery.length >= 2 && setShowSearch(true)}
                placeholder="Search products..."
                className={`w-64 pl-10 pr-4 py-2 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/50 backdrop-blur-sm border ${isDarkMode ? 'bg-gray-800/50 border-white/20 text-white placeholder-gray-400' : 'bg-white/60 border-white/60 text-gray-800 placeholder-gray-500'}`}
              />
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
              </svg>
            </div>
            {showSearch && searchResults.length > 0 && (
              <div className={`absolute top-full left-0 right-0 mt-2 ${isDarkMode ? 'bg-gray-900/90' : 'bg-white/90'} backdrop-blur-xl shadow-2xl rounded-xl max-h-64 overflow-y-auto z-50 border ${isDarkMode ? 'border-white/10' : 'border-white/50'}`}>
                {searchResults.map((product) => (
                  <Link
                    key={product._id}
                    to={`/products/${product._id}`}
                    onClick={() => {
                      setShowSearch(false);
                      setSearchQuery('');
                    }}
                    className="flex items-center p-3 hover:bg-gray-100 dark:hover:bg-gray-700"
                  >
                    {product.image && (
                      <img src={product.image} alt={product.name} className="w-10 h-10 object-cover rounded mr-3" />
                    )}
                    <div>
                      <p className="font-medium text-gray-800 dark:text-white">{product.name}</p>
                      <p className="text-sm text-gray-500">₹{product.price}/{product.category}</p>
                    </div>
                  </Link>
                ))}
                <Link
                  to={`/products?search=${encodeURIComponent(searchQuery)}`}
                  onClick={() => {
                    setShowSearch(false);
                    setSearchQuery('');
                  }}
                  className="block p-3 text-center text-primary-600 hover:bg-gray-100 dark:hover:bg-gray-700"
                >
                  View all results
                </Link>
              </div>
            )}
          </form>

          <div className="hidden md:flex items-center space-x-1">
            <Link 
              to="/" 
              className={`relative px-4 py-2 rounded-xl font-medium transition-all duration-300 group ${isDarkMode ? 'text-gray-300 hover:text-white hover:bg-white/10' : 'text-gray-700 hover:text-primary-600 hover:bg-primary-50'}`}
            >
              <span className="relative z-10">Home</span>
              {/* Animated Underline */}
              <span className="absolute bottom-1 left-4 right-4 h-0.5 bg-gradient-to-r from-primary-500 to-secondary-500 transform scale-x-0 group-hover:scale-x-100 transition-transform duration-300 origin-left rounded-full"></span>
            </Link>
            <Link 
              to="/products" 
              className={`relative px-4 py-2 rounded-xl font-medium transition-all duration-300 group ${isDarkMode ? 'text-gray-300 hover:text-white hover:bg-white/10' : 'text-gray-700 hover:text-primary-600 hover:bg-primary-50'}`}
            >
              <span className="relative z-10">Products</span>
              {/* Animated Underline */}
              <span className="absolute bottom-1 left-4 right-4 h-0.5 bg-gradient-to-r from-primary-500 to-secondary-500 transform scale-x-0 group-hover:scale-x-100 transition-transform duration-300 origin-left rounded-full"></span>
            </Link>
          </div>

          <div className="flex items-center space-x-2">
            <button
              onClick={toggleTheme}
              className={`relative p-2.5 rounded-xl transition-all duration-300 transform hover:scale-110 active:scale-95 group overflow-hidden ${isDarkMode ? 'text-gray-300 hover:text-yellow-400 hover:bg-white/10' : 'text-gray-600 hover:text-primary-600 hover:bg-primary-100/50'}`}
              aria-label="Toggle dark mode"
            >
              {/* Button Glow Effect */}
              <span className="absolute inset-0 bg-gradient-to-r from-primary-500/0 via-primary-500/30 to-primary-500/0 opacity-0 group-hover:opacity-100 transition-opacity duration-300 transform -skew-x-12 group-hover:animate-shimmer"></span>
              {isDarkMode ? (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z" />
                </svg>
              ) : (
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z" />
                </svg>
              )}
            </button>

            <Link to="/wishlist" className={`relative p-2.5 rounded-xl transition-all duration-300 transform hover:scale-110 active:scale-95 group overflow-hidden ${isDarkMode ? 'text-gray-300 hover:text-red-400 hover:bg-white/10' : 'text-gray-600 hover:text-red-500 hover:bg-red-50/50'}`}>
              {/* Heart Pulse Effect */}
              <span className="absolute inset-0 bg-red-500/20 rounded-xl opacity-0 group-hover:opacity-100 animate-pulse"></span>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4.318 6.318a4.5 4.5 0 000 6.364L12 20.364l7.682-7.682a4.5 4.5 0 00-6.364-6.364L12 7.636l-1.318-1.318a4.5 4.5 0 00-6.364 0z" />
              </svg>
            </Link>

            <Link to="/cart" className={`relative p-2.5 rounded-xl transition-all duration-300 transform hover:scale-110 active:scale-95 group overflow-hidden ${isDarkMode ? 'text-gray-300 hover:text-primary-400 hover:bg-white/10' : 'text-gray-600 hover:text-primary-600 hover:bg-primary-50/50'}`}>
              {/* Cart Glow Effect */}
              <span className="absolute inset-0 bg-gradient-to-r from-primary-500/0 via-primary-500/20 to-primary-500/0 opacity-0 group-hover:opacity-100 transition-opacity duration-300"></span>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z" />
              </svg>
              {cartCount > 0 && (
                <span className="absolute -top-1 -right-1 w-5 h-5 bg-red-500 text-white text-xs rounded-full flex items-center justify-center">
                  {cartCount}
                </span>
              )}
            </Link>

            {user || isAdminAuthenticated() ? (
              <div className="flex items-center space-x-4">
                {/* Admin Notification Bell - Only show when admin is authenticated */}
                {isAdminAuthenticated() && (
                  <AdminNotifications onPaymentClick={handleNotificationClick} />
                )}
                
                {isAdminAuthenticated() && (
                  <Link to="/admin" className="text-purple-600 hover:text-purple-700 dark:text-purple-400 font-medium">
                    {getAdminUser()?.name || 'Admin'}
                  </Link>
                )}
                {user && !isAdminAuthenticated() && (
                  <Link to="/account" className="text-gray-600 hover:text-primary-600 transition-colors dark:text-gray-300 dark:hover:text-primary-400">
                    <span className="flex items-center space-x-2">
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
                      </svg>
                      <span className="hidden md:inline">{user.name}</span>
                    </span>
                  </Link>
                )}
                <button
                  onClick={handleLogout}
                  className={`p-2.5 rounded-xl transition-all duration-300 transform hover:scale-110 ${isDarkMode ? 'text-gray-300 hover:text-red-400 hover:bg-white/10' : 'text-gray-600 hover:text-red-500 hover:bg-red-50/50'}`}
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
                  </svg>
                </button>
              </div>
            ) : (
              <div className="flex items-center space-x-2">
                <Link 
                  to="/login" 
                  className={`px-4 py-2 rounded-xl font-medium transition-all duration-300 ${isDarkMode ? 'text-gray-300 hover:text-white hover:bg-white/10' : 'text-gray-700 hover:text-primary-600 hover:bg-primary-50/50'}`}
                >
                  Login
                </Link>
                <Link 
                  to="/register" 
                  className={`px-4 py-2 rounded-xl font-medium transition-all duration-300 bg-gradient-to-r from-primary-500 to-secondary-500 text-white hover:shadow-lg hover:shadow-primary-500/30 transform hover:scale-105`}
                >
                  Sign Up
                </Link>
              </div>
            )}
          </div>
        </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
